const ACCION_POR_CATEGORIA = {
  cliente_nuevo: 'ficha_creada',
  expediente_existente: 'nota_expediente',
  plazo: 'marcado_urgente',
  ruido: 'archivado',
  duda: 'revision_humana',
};

// Si el modelo reconoce una segunda categoría defendible, su propia confianza no puede
// pasar de aquí. La confianza verbalizada de un LLM satura cerca de 1 (en la primera
// evaluación, 27 de 28 casos cayeron en [0.9-1.0] incluidos los 4 errores), así que el
// umbral solo protege si algo la baja. Lo que la baja es un hecho declarado por el propio
// modelo — "existe otra lectura defendible" — no su sensación de seguridad.
const CONFIANZA_MAX_CON_RIVAL = 0.6;

return $input.all().map((item, i) => {
  let raw = item.json.output;
  if (typeof raw === 'string') {
    const match = raw.match(/\{[\s\S]*\}/);
    raw = JSON.parse(match ? match[0] : raw);
  }

  // Normaliza confianza: si el modelo no la devuelve o no es numérica, fuerza 0.
  // 0 siempre dispara revisión humana vía el umbral; nunca cuela el correo sin control.
  let confianza = raw.confianza;
  confianza = (typeof confianza === 'number' && Number.isFinite(confianza)) ? confianza : 0;

  const categoria = raw.categoria;

  // Rival ausente o mal formada se trata como 'ninguna': el prompt la pide, pero el sistema
  // no puede caerse si el modelo la omite. Si la rival repite la categoría elegida no es
  // rival de nada.
  const rival = typeof raw.categoria_rival === 'string' ? raw.categoria_rival : 'ninguna';
  const hay_rival = rival !== 'ninguna' && rival !== categoria;
  if (hay_rival) confianza = Math.min(confianza, CONFIANZA_MAX_CON_RIVAL);

  // Umbral asimétrico. Archivar como ruido es la única rama que no deja rastro: nadie va a
  // volver a mirar ese correo, así que exige más confianza que las demás. Si la variable no
  // está definida, Number(undefined) es NaN y se cae al umbral general.
  const umbral_base = Number($env.TRIAGE_CONFIANZA_UMBRAL);
  const umbral_ruido = Number($env.TRIAGE_CONFIANZA_UMBRAL_RUIDO);
  const umbral = (categoria === 'ruido' && Number.isFinite(umbral_ruido)) ? umbral_ruido : umbral_base;

  // Mismo operador (>=) y mismos operandos que usará 'IF Confianza Suficiente': el umbral
  // aplicado viaja con el item (y por la fila de triage_log) para que el IF no tenga que
  // recalcularlo y no puedan divergir. Si el umbral no es numérico, NaN hace la comparación
  // false en ambos sitios: falla cerrado a revisión humana.
  const confianza_ok = confianza >= umbral;

  const accion = confianza_ok ? (ACCION_POR_CATEGORIA[categoria] || 'revision_humana') : 'revision_humana';
  const decidido_por = confianza_ok ? 'sistema' : 'umbral';

  return {
    json: { ...raw, categoria_rival: rival, confianza, umbral_aplicado: umbral, accion, decidido_por },
    pairedItem: { item: i },
  };
});
